'use strict';
const $=s=>document.querySelector(s),main=$('#main'),modal=$('#modal');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dt=x=>{if(!x||!ABC.validDate(x))return 'Belum diisi';return new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',day:'numeric',month:'short',year:'numeric'}).format(new Date(x+'T12:00:00+07:00'))};
const ts=x=>new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(x))+' WIB';
const opts=(arr,value)=>arr.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return '<option value="'+esc(v)+'" '+(v===value?'selected':'')+'>'+esc(t)+'</option>'}).join('');
const button=(text,action,extra='',kind='')=>'<button type="button" class="btn '+kind+'" data-action="'+action+'" '+extra+'>'+text+'</button>';
const badge=(s,outline=false)=>'<span class="status '+(outline?'outline':({'Diajukan':'blue','Disepakati Mentor':'blue','Tercatat':'lime','Diterbitkan':'lime','Perlu perbaikan':'amber','Sudah diperiksa':'blue'}[s]||''))+'">'+esc(s)+'</span>';
let state={role:'mentee',personId:'mentee-01',groupId:'rajawali',period:'M6',realm:'user',page:'home',abcId:null,queue:false};
let dbs={},blocked={},draft=null,editKind=null,dirty=false,errors={},filter={q:'',activity:'',status:'',commitment:''},peopleFilter={q:'',field:'',group:''};
const PREF='ipbleap-workspace-integrated-view-v1';
try{const s=JSON.parse(localStorage.getItem(PREF)||'null');if(s&&LEAP.ROLES[s.role]&&LEAP.person(s.personId)&&LEAP.GROUPS[s.groupId]&&LEAP.PERIODS[s.period]&&['user','example'].includes(s.realm))state={...state,...s,page:'home',abcId:null,queue:false}}catch{}
const query=new URLSearchParams(location.search);
const roleMap={mentee:'mentee',asmen:'asmen',mentor:'mentor',pengurus:'program',bendahara:'finance',superadmin:'system'};
const siteRole=r=>({program:'pengurus',finance:'bendahara',system:'superadmin'}[r]||r);
const requestedRole=query.get('role')||sessionStorage.getItem('ipb-leap-preview-role');
if(roleMap[requestedRole])state.role=roleMap[requestedRole];
if(LEAP.person(query.get('person')))state.personId=query.get('person');
if(LEAP.GROUPS[query.get('group')])state.groupId=query.get('group');
if(['user','example'].includes(query.get('realm')))state.realm=query.get('realm');
if(LEAP.PERIODS[query.get('period')])state.period=query.get('period');
if(query.get('abc'))state.abcId=query.get('abc');
const routePages={'POC.dc.html':'poc','WorksheetABC.dc.html':'abc','Raport.dc.html':'raport','Penilaian.dc.html':'raport','UpdateProgres.dc.html':'progress'};
const allowedPages=['home','poc','abc','abc-detail','raport','progress'];
state.page=allowedPages.includes(query.get('page'))?query.get('page'):routePages[location.pathname.split('/').pop()]||'home';
if(query.get('page')==='abc-form'&&state.abcId)state.page='abc-detail';
if(query.has('person')&&!query.has('group'))state.groupId=LEAP.person(state.personId).group;
if(['asmen','mentor'].includes(state.role)&&state.page==='abc'&&(query.get('queue')==='1'||location.pathname.endsWith('/WorksheetABC.dc.html')&&!query.has('page')))state.queue=true;
let monthlyPeriod=/^20\d\d-(0[1-9]|1[0-2])$/.test(query.get('month')||'')?query.get('month'):'2026-09';
let navbarRoot;
function syncRoute(){const q=new URLSearchParams(location.search);for(const [k,v] of Object.entries({role:siteRole(state.role),person:state.personId,group:state.groupId,page:state.page,period:state.period,realm:state.realm,month:monthlyPeriod}))q.set(k,v);if(state.page==='abc'&&state.queue)q.set('queue','1');else q.delete('queue');if(state.abcId)q.set('abc',state.abcId);else q.delete('abc');history.replaceState(null,'',location.pathname+'?'+q.toString());try{sessionStorage.setItem('ipb-leap-preview-role',siteRole(state.role))}catch{}}
function mountNavbar(){const host=document.getElementById('originalNavbar');if(!host)return;if(window.getDC&&window.React&&window.ReactDOM){navbarRoot??=window.ReactDOM.createRoot(host);navbarRoot.render(window.React.createElement(window.getDC('Navbar'),{role:siteRole(state.role),active:['asmen','mentor'].includes(state.role)?'kelompok':'program',actorName:LEAP.actor(ctx()),menteeName:person().name,initials:person().initial,groupName:LEAP.GROUPS[person().group].name}));}else{host.innerHTML='<a class="btn" href="index.html">IPB LEAP · Halaman masuk</a>';}}
function storageError(text){$('#storageError').hidden=false;$('#storageError').innerHTML='<b>Data belum tersimpan.</b> '+esc(text)+'<br>Isian tetap terbuka. Gunakan Salin isian sebelum menutup atau memuat ulang halaman.'}
function load(which){try{dbs[which]=LEAP.parse(localStorage.getItem(LEAP.KEYS[which]));blocked[which]=false}catch(e){dbs[which]=LEAP.empty();blocked[which]=true;storageError('Penyimpanan '+(which==='user'?'catatan saya':'contoh')+' tidak dapat dibaca: '+e.message+' Data lama tidak ditimpa.')}}
load('user');load('example');
const db=()=>dbs[state.realm],ctx=()=>({role:state.role,personId:state.personId,groupId:state.groupId}),person=()=>LEAP.person(state.personId);
function prefs(){try{localStorage.setItem(PREF,JSON.stringify({role:state.role,personId:state.personId,groupId:state.groupId,period:state.period,realm:state.realm}))}catch{}}
function transact(fn,errorId=null){if(blocked[state.realm]){storageError('Ruang penyimpanan ini belum dapat digunakan.');return null}const next=LEAP.clone(db());let result;try{result=fn(next)}catch(e){if(errorId&&document.getElementById(errorId))document.getElementById(errorId).textContent=e.message;else toast(e.message);return null}try{dbs[state.realm]=LEAP.persist(localStorage,LEAP.KEYS[state.realm],db(),next);$('#storageError').hidden=true;return result===undefined?true:result}catch(e){storageError(e.message);return null}}
let toastTimer;function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500)}
function dialog(html){modal.innerHTML=html;modal.showModal()}
function closeModal(){modal.close()}
function confirmAction(title,text,action,label='Lanjutkan'){dialog('<h2>'+title+'</h2><p>'+text+'</p><div class="row">'+button('Kembali','modal-close')+'<button type="button" class="btn primary" id="confirmAction">'+label+'</button></div>');$('#confirmAction').onclick=()=>{const ok=action();if(ok!==false)closeModal()}}
function unsavedText(){return [...main.querySelectorAll('form input,form select,form textarea')].map(el=>{if(el.type==='checkbox')return (main.querySelector('label[for="'+el.id+'"]')?.textContent||el.name)+': '+(el.checked?'Ya':'Tidak');return (main.querySelector('label[for="'+el.id+'"]')?.textContent||el.name)+': '+el.value}).join('\n')}
async function copyRaw(text){try{await navigator.clipboard.writeText(text);toast('Teks berhasil disalin.')}catch{dialog('<h2>Salin teks</h2><p>Penyalinan otomatis tidak tersedia. Pilih teks di bawah dan salin secara manual.</p><textarea id="manualCopy" aria-label="Teks untuk disalin" readonly>'+esc(text)+'</textarea><div class="row">'+button('Tutup','modal-close')+'</div>');$('#manualCopy').select()}}
function leave(next){if(!dirty){next();return}dialog('<h2>Isian belum disimpan</h2><p>Simpan isian agar tersedia setelah muat ulang, atau salin terlebih dahulu.</p><div class="row">'+button('Tetap mengisi','modal-close')+button('Salin isian','copy-unsaved')+'<button class="btn" id="leaveUnsaved">Lanjut tanpa menyimpan</button></div>');$('#leaveUnsaved').onclick=()=>{dirty=false;closeModal();next()}}
function normalize(){if(!['finance','system'].includes(state.role)){const people=LEAP.visiblePeople(ctx());if(!people.some(p=>p.id===state.personId))state.personId=people[0].id}if(['finance','system'].includes(state.role))state.page='home';if(state.role==='mentee')state.queue=false}
function navigate(page,extra={}){leave(()=>{Object.assign(state,{page,queue:false},extra);normalize();draft=null;editKind=null;errors={};if(page==='poc-form'){const r=db().pocs[state.personId];if(state.role!=='mentee'||r&&!['Draft','Perlu perbaikan'].includes(LEAP.last(r).status)){state.page='poc'}else{draft=LEAP.clone(LEAP.last(r)?.data||LEAP.pocBlank(state.personId));editKind='poc'}}if(page==='abc-form'){state.abcId=extra.abcId||null;const r=state.abcId?db().abcs.find(x=>x.id===state.abcId):null;if(state.role!=='mentee'||r&&!['Draft','Perlu perbaikan'].includes(ABC.status(r))){state.page='abc'}else{draft=r?LEAP.clone(ABC.latest(r).data):LEAP.abcBlank(db(),state.personId);editKind='abc'}}if(page==='assessment'){const r=LEAP.review(db(),state.personId,state.period);if(!LEAP.canAssess(ctx(),state.period)||LEAP.published(r)){state.page='raport'}else{draft=LEAP.clone(LEAP.last(r)?.data||LEAP.reviewBlank(db(),state.personId,state.period));editKind='assessment'}}prefs();render(true)})}
function changeRole(role){leave(()=>{const previous=state.page;if(['asmen','mentor'].includes(role))state.groupId=person().group;state.role=role;state.page=previous.startsWith('poc')?'poc':previous==='abc-detail'||previous==='abc-form'?(state.abcId?'abc-detail':'abc'):['raport','assessment'].includes(previous)?'raport':previous==='progress'?'progress':'home';state.queue=false;draft=null;dirty=false;normalize();prefs();render(true)})}
function switchRealm(){leave(()=>{const target=state.realm==='user'?'example':'user';if(target==='example'&&!Object.keys(dbs.example.pocs).length&&!dbs.example.abcs.length){if(blocked.example){storageError('Ruang contoh tidak dapat dibaca.');return}try{dbs.example=LEAP.persist(localStorage,LEAP.KEYS.example,dbs.example,LEAP.exampleStore())}catch(e){storageError(e.message);return}}state.realm=target;state.page='home';state.queue=false;draft=null;dirty=false;errors={};prefs();render(true);toast(target==='example'?'Ruang contoh fiktif dibuka. Catatanmu tetap terpisah.':'Kembali ke catatan saya.')})}
function menuItem(title,subtitle,page,extra=''){return '<button data-action="nav" data-page="'+page+'" '+extra+'>'+title+'<small>'+subtitle+'</small></button>'}
function header(){const c=ctx(),p=person(),title=state.role==='mentee'?p.name:LEAP.actor(c);let links='';let menu='';if(state.role==='mentee'){menu=menuItem('Personal Outcome Contract','Arah, KPI, dan target yang disepakati','poc')+menuItem('Worksheet ABC','Refleksi kegiatan dan tindak lanjut','abc')+menuItem('Raport','Perkembangan dan hasil yang diterbitkan','raport')}if(['asmen','mentor'].includes(state.role)){menu=menuItem('Ringkasan kelompok','Mentee dan pekerjaan pendampingan','home')+menuItem('Worksheet ABC kelompok','Antrean catatan dan tindak lanjut','abc','data-queue="true"')+menuItem('POC mentee terpilih','Lihat arah dan kesepakatan target','poc')+menuItem('Penilaian & bukti','Raport dan bahan penilaian mentee','raport')}if(state.role==='program'){menu=menuItem('Monitoring program','Lihat mentee dalam cohort','home')+menuItem('Penilaian & bukti','Raport serta penilaian akhir','raport')+menuItem('ABC mentee terpilih','Baca refleksi dan jejak tindakan','abc')+menuItem('POC mentee terpilih','Baca target yang disepakati','poc')}
links='<button class="nav-link '+(state.page==='home'?'active':'')+'" data-action="nav" data-page="home">'+(state.role==='system'?'Sistem':state.role==='finance'?'Keuangan':'Beranda')+'</button>'+(menu?'<details class="nav-drop"><summary class="nav-trigger '+(state.page!=='home'?'active':'')+'">'+(['asmen','mentor'].includes(state.role)?'Kelompok':'Program')+' <span aria-hidden="true">⌄</span></summary><div class="dropdown">'+menu+'</div></details>':'')+'<button class="nav-link" data-action="guide">Panduan</button>';
if(!document.getElementById('originalNavbar'))$('#header').innerHTML='<div id="originalNavbar"></div><details class="mobile-workspace-menu"><summary>Menu workspace</summary><div id="mobileWorkspaceLinks"></div></details>';
const home=state.role==='mentee'?'BerandaMentee.dc.html':state.role==='finance'?'Keuangan.dc.html':state.role==='system'?'SuperAdmin.dc.html':state.role==='program'?'BerandaPengurus.dc.html':'Monitoring.dc.html';
$('#mobileWorkspaceLinks').innerHTML='<a href="'+home+'?role='+siteRole(state.role)+'">Beranda</a>'+links+'<a href="Kalender.dc.html">Kalender</a><a href="Event.dc.html">Event</a><a href="Chat.dc.html">Chat</a><a href="'+(state.role==='mentee'?'BerandaMentee.dc.html':'Proker.dc.html')+'">Task</a><a href="index.html">Ganti peran</a>';
mountNavbar();
let controls='<label>Pratinjau peran<select id="roleSelect" aria-label="Pratinjau peran">'+opts(Object.entries(LEAP.ROLES),state.role)+'</select></label>';
if(['asmen','mentor'].includes(state.role))controls+='<label>Kelompok pendamping<select id="groupSelect" aria-label="Kelompok pendamping">'+opts(Object.entries(LEAP.GROUPS).map(([id,x])=>[id,x.name]),state.groupId)+'</select></label>';
if(!['finance','system'].includes(state.role)){const people=state.role==='mentee'?LEAP.PEOPLE:LEAP.visiblePeople(c);controls+='<label>'+(state.role==='mentee'?'Akun mentee contoh':'Mentee yang ditinjau')+'<select id="personSelect" aria-label="'+(state.role==='mentee'?'Akun mentee contoh':'Mentee yang ditinjau')+'">'+opts(people.map(x=>[x.id,x.name+' · '+LEAP.GROUPS[x.group].name]),state.personId)+'</select></label>'}
$('#simulation').innerHTML='<div class="simbar"><div class="sim-inner"><div class="sim-label"><b>PRATINJAU · '+(state.realm==='example'?'CONTOH FIKTIF':'CATATAN SAYA')+'</b>Peran dan identitas adalah simulasi, bukan autentikasi.</div>'+controls+'<div class="realm-control">'+button(state.realm==='example'?'← Catatan saya':'Lihat contoh','realm','','small')+'</div></div></div>';
$('#footer').innerHTML='IPB LEAP · POC, Worksheet ABC &amp; Raport · Waktu Asia/Jakarta (WIB)<br>Hanya tersimpan di browser ini. Pengajuan, kesepakatan, dan penerbitan adalah simulasi lokal; tanpa email atau notifikasi nyata.';
}
function pagehead(title,desc,actions=''){return '<div class="pagehead"><div><div class="eyebrow">'+(state.role==='mentee'?'Perjalanan pengembangan':state.role==='program'?'Program & pendampingan':['asmen','mentor'].includes(state.role)?'Pendampingan · '+esc(LEAP.GROUPS[state.groupId].name):'Ruang kerja sesuai peran')+'</div><h1>'+title+'</h1><p>'+desc+'</p></div><div class="row">'+actions+'</div></div>'}
function realmNote(){return state.realm==='example'?'<div class="notice example row spread"><span><b>Ruang contoh fiktif.</b> Seluruh data dan tautan di sini hanya untuk latihan. Perubahan tetap terpisah dari catatan saya.</span>'+button('Kembali ke catatan saya','realm','','small')+'</div>':''}
function identityContext(){const p=person();return '<div class="context"><div class="person"><span class="avatar">'+p.initial+'</span><div><div class="name">'+esc(p.name)+' <span class="tag">Identitas contoh</span></div><p class="hint">'+esc(LEAP.GROUPS[p.group].name)+' · '+esc(BIDANG[p.field].nama)+' · '+esc(p.pathway)+'</p></div></div><div class="context-links">'+button('POC','nav','data-page="poc"',state.page.startsWith('poc')?'active':'')+button('Worksheet ABC','nav','data-page="abc"',state.page.startsWith('abc')&&!state.queue?'active':'')+button('Raport','nav','data-page="raport"',state.page==='raport'||state.page==='assessment'?'active':'')+'</div></div>'}
function render(scroll=false){normalize();syncRoute();document.title=({'home':'Perjalanan pengembangan','poc':'Personal Outcome Contract','poc-form':'Personal Outcome Contract','abc':'Worksheet ABC','abc-form':'Worksheet ABC','abc-detail':'Worksheet ABC','raport':'Raport','assessment':'Penilaian & bukti','progress':'Update progres'}[state.page]||'Workspace')+' · IPB LEAP';header();let html='';if(state.role==='finance')html=financeHome();else if(state.role==='system')html=systemHome();else if(state.page==='home')html=state.role==='mentee'?menteeHome():groupHome();else if(state.page==='progress')html=progressView();else if(state.page==='poc')html=pocView();else if(state.page==='poc-form')html=pocForm();else if(state.page==='abc')html=abcList();else if(state.page==='abc-form')html=abcForm();else if(state.page==='abc-detail'){const record=db().abcs.find(r=>r.id===state.abcId);if(record&&LEAP.access(ctx(),record.menteeId))html=abcDetail();else{state.page='abc';state.abcId=null;html=abcList();}}else if(state.page==='raport')html=raportView();else if(state.page==='assessment')html=assessmentForm();main.innerHTML=realmNote()+(state.page!=='home'&&!state.queue&&!['finance','system'].includes(state.role)?identityContext():'')+html;if(state.page==='abc')drawAbcs();if(state.page==='home'&&['asmen','mentor','program'].includes(state.role))drawPeople();if(state.page==='abc-form')updateAbcGuide();if(scroll){window.scrollTo(0,0);main.focus({preventScroll:true})}}
function empty(title,text,actions=''){return '<div class="empty"><div class="symbol">↗</div><h3>'+title+'</h3><p>'+text+'</p><div class="row">'+actions+'</div></div>'}
function task(title,desc,action,extra='',icon='↗'){return '<div class="task"><span class="task-icon">'+icon+'</span><div><strong>'+title+'</strong><p>'+desc+'</p></div>'+button('Buka','nav',action+' '+extra,'small')+'</div>'}
function menteeHome(){const p=person(),pr=db().pocs[p.id],av=LEAP.abcs(db(),p.id),published=LEAP.published(LEAP.review(db(),p.id,state.period));let tasks='';if(!pr)tasks+=task('Mulai Personal Outcome Contract','Tetapkan arah pengembangan saat kamu sudah siap.','data-page="poc"','','P');else if(['Draft','Perlu perbaikan'].includes(LEAP.last(pr).status))tasks+=task(LEAP.last(pr).status==='Perlu perbaikan'?'Perbaiki POC':'Lanjutkan draft POC','Arah dan target disusun bersama mentor.','data-page="poc"','','P');for(const r of av.filter(x=>['Draft','Perlu perbaikan'].includes(ABC.status(x))).slice(0,3))tasks+=task((ABC.status(r)==='Draft'?'Lanjutkan ABC ':'Perbaiki ABC ')+esc(ABC.latest(r).data.activity||'kegiatan baru'),'Catatan '+ABC.status(r).toLowerCase()+'.','data-page="abc-detail"','data-id="'+r.id+'"','A');for(const r of av.filter(ABC.pending).slice(0,2))tasks+=task('Tindak lanjuti komitmen '+esc(ABC.latest(r).data.activity),'Bawa laporan tindakan dan hasil aktual saat check-in.','data-page="abc-detail"','data-id="'+r.id+'"','C');if(!av.length)tasks+=task('Tulis ABC setelah kegiatan','ABC boleh diisi sebelum POC tersedia, termasuk Kick-off.','data-page="abc-form"','','A');
return '<div class="notice"><a href="BerandaMentee.dc.html?role=mentee">← Kembali ke Beranda</a> · Hero, nilai bulanan, jadwal, dan kegiatanmu tetap tersedia di Beranda.</div><section class="hero"><div><div class="eyebrow">Learn. Connect. Grow.</div><h1>Halo, '+esc(p.name.split(' ')[0])+'.<br>Langkah kecil, perubahan nyata.</h1><p>Satu perjalanan untuk menentukan arah, merefleksikan pengalaman, dan melihat hasil pengembanganmu.</p><div class="row">'+button('＋ Buat ABC baru','nav','data-page="abc-form"','lime')+button('Lihat Raport','nav','data-page="raport"')+'</div></div><div class="journey"><div><b>01</b><span>POC</span><small>Tentukan arah</small></div><div><b>02</b><span>ABC</span><small>Refleksi &amp; tindakan</small></div><div><b>03</b><span>Raport</span><small>Lihat perkembangan</small></div></div></section>'+identityContext()+'<div class="layout"><section class="panel"><div class="section-head"><h2>Yang perlu kamu lakukan</h2><p>Fokus pada langkah berikutnya yang paling membantu.</p></div>'+(tasks||empty('Catatanmu sudah tertata','Lanjutkan tindakan yang disepakati dan tulis refleksi setelah kegiatan.',button('Buat ABC baru','nav','data-page="abc-form"','primary')))+'</section><aside class="aside"><section class="panel"><h3>Arah pengembangan</h3><p>'+esc(LEAP.last(pr)?.data.title||'POC belum dibuat. Kamu tetap bisa mulai dari refleksi kegiatan.')+'</p><div class="row" style="margin-top:13px">'+badge(LEAP.last(pr)?.status||'Belum tersedia')+'</div>'+button('Buka POC →','nav','data-page="poc"','subtle')+'</section><section class="panel"><h3>Raport terbaru</h3><p>'+esc(published?.data.summary||'Hasil penilaian yang sudah diterbitkan akan muncul di sini.')+'</p><p class="hint" style="margin-top:10px">'+LEAP.PERIODS[state.period]+'</p>'+button('Baca perkembangan →','nav','data-page="raport"','subtle')+'</section></aside></div>'}
function groupHome(){const ids=LEAP.visiblePeople(ctx()).map(p=>p.id),av=db().abcs.filter(r=>ids.includes(r.menteeId));return pagehead(state.role==='program'?'Perkembangan cohort':'Kelompok '+esc(LEAP.GROUPS[state.groupId].name),state.role==='program'?'Pilih mentee untuk meninjau arah, jejak tindakan, dan hasil penilaian.':'Pilih mentee, lalu lanjutkan pendampingan dengan konteks yang sama.',state.role==='asmen'?button('Periksa ABC kelompok','nav','data-page="abc" data-queue="true"','primary'):'')+'<div class="grid3 stats"><div class="metric"><b>'+ids.length+'</b><span>Mentee dalam cakupan</span></div><div class="metric"><b>'+av.filter(r=>ABC.status(r)==='Diajukan').length+'</b><span>ABC menunggu pemeriksaan</span></div><div class="metric"><b>'+av.filter(ABC.pending).length+'</b><span>Komitmen menunggu tindak lanjut</span></div></div><section class="panel"><div class="section-head"><h2>'+(state.role==='program'?'Mentee dalam cohort':'Mentee kelompok')+'</h2><p>Tidak ada peringkat. Ringkasan membantu menentukan pekerjaan pendampingan.</p></div><div class="toolbar"><label>Pencarian<input id="peopleSearch" type="search" placeholder="Cari nama mentee…" value="'+esc(peopleFilter.q)+'" aria-label="Cari mentee"></label><label>Bidang<select id="peopleField" aria-label="Filter Bidang">'+opts([['','Semua Bidang'],...Object.entries(BIDANG).map(([id,x])=>[id,x.nama])],peopleFilter.field)+'</select></label>'+(state.role==='program'?'<label>Kelompok<select id="peopleGroup" aria-label="Filter kelompok">'+opts([['','Semua kelompok'],...Object.entries(LEAP.GROUPS).map(([id,x])=>[id,x.name])],peopleFilter.group)+'</select></label>':'')+'</div><div id="peopleCards" class="grid3"></div></section>'}
function drawPeople(){const ps=LEAP.visiblePeople(ctx()).filter(p=>(!peopleFilter.q||p.name.toLowerCase().includes(peopleFilter.q.toLowerCase()))&&(!peopleFilter.field||p.field===peopleFilter.field)&&(state.role!=='program'||!peopleFilter.group||p.group===peopleFilter.group));$('#peopleCards').innerHTML=ps.length?ps.map(p=>{const av=LEAP.abcs(db(),p.id),pv=LEAP.last(db().pocs[p.id]);return '<article class="person-card"><div class="row"><span class="avatar">'+p.initial+'</span><div><h3>'+esc(p.name)+'</h3><div class="meta">'+LEAP.GROUPS[p.group].name+' · '+esc(p.pathway)+'</div></div></div><p class="hint">'+esc(BIDANG[p.field].nama)+'</p><div class="labels">'+badge('POC · '+(pv?.status||'Belum ada'))+'<span class="status outline">'+av.length+' ABC</span></div><p class="hint">'+av.filter(ABC.pending).length+' komitmen menunggu tindak lanjut</p>'+button('Buka perkembangan →','nav','data-page="raport" data-person="'+p.id+'"')+'</article>'}).join(''):'<p class="hint">Tidak ada mentee yang sesuai dengan filter.</p>'}
function financeHome(){return pagehead('Ruang Bendahara','Akses modul mengikuti tanggung jawab peran.')+'<div class="restricted"><section class="panel"><div class="formtitle"><span class="letter lime">Rp</span><div><h2>Fokus pada keuangan program</h2><p><a href="Keuangan.dc.html?role=bendahara">Buka Keuangan →</a></p><p>Integrasi POC, ABC, dan Raport tidak menambah akses isi refleksi untuk Bendahara.</p></div></div><p class="data-text">Pada rancangan ini, Bendahara tetap bekerja di ruang Keuangan. Jika merangkap petugas penilaian, penugasan tambahan perlu diberikan secara jelas pada sistem sebenarnya.</p><div class="notice">Pratinjau lokal ini berfokus pada tiga modul pengembangan. Data keuangan dan transaksi tidak disalin ke prototipe.</div>'+button('Lihat pembagian peran','guide','','primary')+'</section></div>'}
function systemHome(){const descriptions={mentee:'Mengisi POC dan ABC sendiri, melaporkan tindakan, membaca hasil terbit.',asmen:'Memeriksa ABC, mencatat tindak lanjut, dan mencatat kesepakatan POC kelompok.',mentor:'Menyepakati POC, membaca ABC, dan menilai Review berkala mentee binaan.',program:'Meninjau cohort serta menilai dan menerbitkan hasil akhir M12.',finance:'Fokus Keuangan; tanpa akses bawaan ke isi tiga modul ini.',system:'Mengelola sistem, peran, dan audit; tanpa kewenangan penilaian program otomatis.'};return pagehead('Konsol Super Admin','Lihat pembagian akses dan jejak simulasi. Pengaturan akun nyata tidak tersedia.')+'<section class="panel"><div class="section-head"><h2>Pembagian akses modul</h2><p>Simulasi pembatasan antarmuka; belum merupakan autentikasi atau otorisasi server.</p></div><div class="role-grid">'+Object.entries(LEAP.ROLES).map(([id,label])=>'<div class="permission-card"><h3>'+label+'</h3><p>'+descriptions[id]+'</p></div>').join('')+'</div></section><section class="panel"><div class="section-head"><h2>Audit aktivitas lokal</h2><p>Metadata tindakan; isi refleksi dan target tidak ditampilkan di ruang sistem.</p></div>'+(db().audit.length?[...db().audit].reverse().slice(0,30).map(x=>'<div class="audit-line"><b>'+esc(x.type)+'</b> · '+esc(LEAP.ROLES[x.role])+'<br><span class="muted">'+ts(x.at)+' · ID mentee '+esc(x.menteeId)+'</span></div>').join(''):'<p class="hint">Belum ada aktivitas di ruang penyimpanan ini. Coba alur sebagai Mentee atau buka contoh fiktif.</p>')+'</section>'}
function inputId(path){return 'f-'+path.replace(/[^a-zA-Z0-9_-]/g,'-')}
function field(path,label,type,value,hint='',choices=null){const id=inputId(path),err=errors[path];return '<div class="field"><label for="'+id+'">'+label+'</label>'+(hint?'<p class="hint" id="'+id+'-hint">'+hint+'</p>':'')+(type==='textarea'?'<textarea id="'+id+'" name="'+path+'" rows="3"':type==='select'?'<select id="'+id+'" name="'+path+'"':'<input id="'+id+'" name="'+path+'" type="'+type+'" value="'+esc(value)+'"')+' class="'+(err?'invalid':'')+'" '+(err?'aria-invalid="true" ':'')+'aria-describedby="'+id+'-error'+(hint?' '+id+'-hint':'')+'"'+(type==='textarea'?'>'+esc(value)+'</textarea>':type==='select'?'>'+opts(choices||[],value)+'</select>':'>')+'<span id="'+id+'-error" class="field-error">'+esc(err||'')+'</span></div>'}
function block(label,value){return '<div class="block"><div class="data-label">'+label+'</div><p class="data-text">'+esc(value||'Belum diisi')+'</p></div>'}
function links(value){return value?value.split('\n').map(x=>x.trim()).filter(Boolean).map(x=>'<p style="overflow-wrap:anywhere">'+(ABC.validUrl(x)?'<a href="'+esc(x)+'" target="_blank" rel="noopener noreferrer">'+esc(x)+'</a>':esc(x))+'</p>').join(''):'<p class="hint">Belum ada tautan bukti hasil aktual.</p>'}
function formErrors(){return Object.keys(errors).length?'<div class="notice error" role="alert" id="formErrors"><b>Periksa isian sebelum melanjutkan</b><ul>'+Object.entries(errors).map(([path,msg])=>'<li><a href="#'+inputId(path)+'">'+esc(msg)+'</a></li>').join('')+'</ul><p>Isian tetap utuh dan dapat disimpan sebagai draft.</p></div>':''}
function showErrors(e){errors=e;render();const el=document.getElementById(inputId(Object.keys(e)[0]));el?.focus()}
function saveActions(kind,submitLabel){return '<div class="actions"><p class="save-hint">'+(dirty?'Ada perubahan yang belum disimpan.':'Simpan agar isian tersedia setelah muat ulang.')+' Seluruh tindakan hanya simulasi lokal.</p>'+button('Salin isian','copy-unsaved')+button('Simpan draft',kind==='poc'?'poc-save':kind==='abc'?'abc-save':'assessment-save')+'<button type="submit" class="btn primary">'+submitLabel+'</button></div>'}
function pocForm(){if(!draft)return '';const p=person();return pagehead('Susun Personal Outcome Contract','Arah dan ukuran personal mengikuti baseline, lalu dibahas bersama mentor.',button('← Tinjau POC','nav','data-page="poc"'))+'<div class="step-links"><a href="#poc-direction">01 · Arah</a><a href="#poc-kpis">02 · KPI & target</a><a href="#poc-plan">03 · Rencana & dukungan</a></div><div class="layout"><form id="pocForm" class="stack" novalidate>'+formErrors()+'<section class="panel" id="poc-direction"><div class="formtitle"><span class="letter">01</span><div><h2>Arah pengembangan</h2><p>Periode outcome: Desember 2026–November 2027.</p></div></div><div class="fields">'+field('title','Judul POC *','text',draft.title,'Nama singkat perubahan yang kamu tuju.')+field('summary','Ringkasan arah pengembangan *','textarea',draft.summary)+field('baseline','Kondisi awal saya *','textarea',draft.baseline,'Gunakan angka atau fakta yang dapat diperiksa.')+'<div class="grid2">'+field('baselinePeriod','Periode baseline *','text',draft.baselinePeriod)+field('baselineUrl','Tautan bukti baseline · opsional','url',draft.baselineUrl,'Tautan hanya dicatat, tanpa pembacaan otomatis.')+'</div>'+field('reason','Mengapa saya memilih fokus ini? *','textarea',draft.reason)+field('outcome','Perubahan yang ingin saya capai *','textarea',draft.outcome,'Ceritakan keadaan akhirnya, bukan hanya kegiatannya.')+'</div></section><section class="panel" id="poc-kpis"><div class="section-head"><h2>KPI &amp; target bertahap</h2><p>Gunakan 1–3 KPI personal yang merujuk KPI Bidang. Target M12 menjadi arah outcome akhir.</p></div>'+draft.kpis.map((k,i)=>'<div class="kpi-edit"><div class="row spread"><h3>KPI '+(i+1)+'</h3>'+(draft.kpis.length>1?button('Hapus KPI','remove-kpi','data-index="'+i+'"','small'):'')+'</div><div class="fields">'+field('kpis.'+i+'.fieldKpi','Acuan KPI Bidang *','select',k.fieldKpi,'',BIDANG[p.field].kpis)+field('kpis.'+i+'.name','Nama KPI personal *','text',k.name)+field('kpis.'+i+'.definition','Definisi ukuran *','textarea',k.definition,'Apa yang dihitung atau kondisi apa yang harus terlihat?')+'<div class="grid2">'+field('kpis.'+i+'.type','Jenis indikator','select',k.type,'',[['MENINGKAT','Meningkat'],['MENURUN','Menurun'],['MILESTONE','Milestone / kondisi tercapai']])+field('kpis.'+i+'.unit','Satuan'+(k.type==='MILESTONE'?' · jika relevan':' *'),'text',k.unit,'Contoh: orang, rupiah, hari, atau dokumen.')+'</div>'+field('kpis.'+i+'.baseline','Baseline KPI *','text',k.baseline,'Angka atau keadaan sebelum program.')+'<div class="grid2">'+Object.entries(LEAP.PERIODS).map(([code,label])=>field('kpis.'+i+'.targets.'+code,label+' *','text',k.targets[code],'Target hasil pada periode ini.')).join('')+'</div>'+field('kpis.'+i+'.deadline','Tenggat outcome *','date',k.deadline)+field('kpis.'+i+'.measurement','Cara mengukur *','textarea',k.measurement)+field('kpis.'+i+'.evidencePlan','Rencana bukti *','textarea',k.evidencePlan,'Tentukan sumber bukti yang akan dikumpulkan.')+'</div><details class="history"><summary>Usulan kriteria capaian untuk dibahas bersama mentor</summary><p class="hint">Gunakan kriteria personal yang sesuai ukuran KPI. Prototipe tidak menetapkan batas atau menghitung level otomatis.</p><div class="fields">'+LEAP.LEVELS.slice(1).map(level=>field('kpis.'+i+'.criteria.'+level,level,'text',k.criteria[level])).join('')+'</div></details></div>').join('')+(draft.kpis.length<3?'<div style="margin-top:16px">'+button('＋ Tambah KPI','add-kpi')+'</div>':'')+'</section><section class="panel" id="poc-plan"><div class="formtitle"><span class="letter lime">03</span><div><h2>Rencana 90 hari &amp; dukungan</h2><p>Rencana awal Januari–Maret 2027.</p></div></div><div class="fields">'+draft.steps.map((s,i)=>'<div class="grid2">'+field('steps.'+i+'.action','Langkah utama '+(i+1)+' *','text',s.action)+field('steps.'+i+'.date','Tenggat langkah '+(i+1)+' *','date',s.date)+'</div>').join('')+field('support','Dukungan yang saya perlukan *','textarea',draft.support)+field('risk','Risiko atau hambatan utama *','textarea',draft.risk)+field('mitigation','Cara mengatasi · opsional','textarea',draft.mitigation)+'<label class="check-label" for="'+inputId('declaration')+'"><input id="'+inputId('declaration')+'" name="declaration" type="checkbox" '+(draft.declaration?'checked':'')+'><span>Saya menyusun POC ini dan akan membahasnya bersama mentor.</span></label><span class="field-error">'+esc(errors.declaration||'')+'</span></div>'+saveActions('poc','Ajukan POC lokal →')+'</section></form><aside class="aside"><section class="panel"><h3>Profil mengikuti akun</h3><p>'+esc(BIDANG[p.field].nama)+'<br>Pathway: '+esc(p.pathway)+'</p><div class="notice"><b>North Star Bidang</b><p>'+esc(BIDANG[p.field].north)+'</p></div><p class="hint">'+esc(BIDANG[p.field].arti)+' Target personal tetap berangkat dari baseline dan dibahas dengan mentor.</p></section><section class="panel"><h3>Alur kesepakatan</h3><p>Mentee mengajukan → Mentor memeriksa dan menyepakati → Asmen mencatat kesepakatan serta versinya.</p><div class="notice">Pengajuan dan kesepakatan pada halaman ini hanya simulasi lokal.</div></section></aside></div>'}
function pocData(d,compact=false){return block('Arah pengembangan',d.summary)+block('Kondisi awal',d.baseline)+'<div class="grid2" style="margin-top:17px">'+block('Periode baseline',d.baselinePeriod)+block('Perubahan yang dituju',d.outcome)+'</div>'+(d.baselineUrl?'<div class="evidence"><div class="data-label">Bukti baseline</div>'+links(d.baselineUrl)+'</div>':'')+(!compact?block('Alasan fokus',d.reason):'')+d.kpis.map((k,i)=>'<div class="kpi-result"><div class="row spread"><h3>KPI '+(i+1)+' · '+esc(k.name||'Belum diberi nama')+'</h3><span class="tag">'+({MENINGKAT:'Meningkat',MENURUN:'Menurun',MILESTONE:'Milestone'}[k.type])+'</span></div><p class="hint" style="margin-top:8px">'+esc(k.fieldKpi)+' · '+esc(k.definition)+'</p><div class="baseline-target"><div><span>Baseline</span><strong>'+esc(k.baseline||'—')+' '+esc(k.unit)+'</strong></div><div><span>Target akhir M12</span><strong>'+esc(k.targets.M12||'—')+' '+esc(k.unit)+'</strong></div><div><span>Tenggat</span><strong>'+dt(k.deadline)+'</strong></div></div><div class="grid2">'+Object.entries(LEAP.PERIODS).map(([code,label])=>block(label,(k.targets[code]||'Belum diisi')+' '+k.unit)).join('')+'</div><details class="history"><summary>Cara ukur, rencana bukti &amp; kriteria</summary>'+block('Cara mengukur',k.measurement)+block('Rencana bukti',k.evidencePlan)+LEAP.LEVELS.slice(1).map(level=>block(level,k.criteria[level]||'Belum diusulkan')).join('')+'</details></div>').join('')+(!compact?'<details class="history"><summary>Rencana 90 hari, dukungan &amp; risiko</summary>'+d.steps.map((s,i)=>block('Langkah '+(i+1),(s.action||'Belum diisi')+' · '+dt(s.date))).join('')+block('Dukungan',d.support)+block('Risiko',d.risk)+block('Cara mengatasi',d.mitigation)+'</details>':'')}
function pocView(){const r=db().pocs[state.personId],v=LEAP.last(r),p=person();if(!v)return pagehead('Personal Outcome Contract','Arah, baseline, dan target personal yang disepakati bersama mentor.')+'<section class="panel">'+empty('POC belum tersedia','ABC tetap bisa ditulis sebelum POC tersedia. Identitas, Bidang, dan pathway mengikuti akun contoh.',(state.role==='mentee'?button('Mulai POC','nav','data-page="poc-form"','primary'):'')+button('Buka Worksheet ABC','nav','data-page="abc"'))+'</section>';
let controls=button('Salin teks POC','copy-poc');if(state.role==='mentee'&&['Draft','Perlu perbaikan'].includes(v.status))controls+=button(v.status==='Perlu perbaikan'?'Perbaiki POC':'Lanjutkan draft','nav','data-page="poc-form"','primary');let review='';if(state.role==='mentor'&&v.status==='Diajukan')review='<section class="panel"><h2>Pemeriksaan &amp; kesepakatan Mentor</h2><p class="hint" style="margin:9px 0 17px">Bahas target dengan mentee. Keputusan menambah riwayat tanpa mengubah isi yang diajukan.</p><form id="pocDecisionForm" class="fields" novalidate>'+field('pocDecision','Hasil pemeriksaan','select','Disepakati Mentor','',['Disepakati Mentor','Perlu perbaikan'])+field('pocNote','Catatan Mentor *','textarea','','Jelaskan kesepakatan atau bagian yang perlu diperbaiki.')+'<p class="field-error" id="decisionError" role="alert"></p><button class="btn primary" type="submit">Simpan keputusan lokal</button></form></section>';
if(state.role==='asmen'&&v.status==='Disepakati Mentor')review='<section class="panel"><h2>Catat kesepakatan POC</h2><p class="hint" style="margin:9px 0 17px">Mentee dan Mentor telah menyepakati versi ini. Asmen mencatat kesepakatan, tanpa mengubah target.</p><form id="pocRecordForm" class="fields" novalidate>'+field('recordNote','Catatan pencatatan *','textarea','')+field('recordDate','Tanggal pencatatan *','date',LEAP.today())+'<p class="field-error" id="recordError" role="alert"></p><button class="btn primary" type="submit">Catat kesepakatan lokal</button></form></section>';
return pagehead('Personal Outcome Contract',esc(v.data.title||'Draft arah pengembangan'),controls)+'<div class="row" style="margin-bottom:20px">'+badge(v.status)+'<span class="hint">Versi '+v.number+' · '+ts(v.at)+'</span></div>'+(v.note?'<div class="notice '+(v.status==='Perlu perbaikan'?'warn':'')+'"><b>'+esc(v.actor)+'</b><p>'+esc(v.note)+'</p></div>':'')+'<div class="layout"><div class="stack"><section class="panel"><div class="section-head"><h2>'+esc(v.data.title||'Judul POC belum diisi')+'</h2><p>'+esc(BIDANG[p.field].nama)+' · '+esc(p.pathway)+'</p></div>'+pocData(v.data)+'</section>'+review+'<section class="panel"><h2>Riwayat versi POC</h2><p class="hint" style="margin:8px 0">Versi yang diajukan, keputusan Mentor, dan pencatatan Asmen tetap tersimpan.</p>'+[...r.versions].reverse().map(x=>'<details class="history"><summary>Versi '+x.number+' · '+esc(x.action)+' · '+ts(x.at)+'</summary><div>'+badge(x.status)+'<p class="hint">'+esc(x.actor)+'</p>'+(x.note?block('Catatan',x.note):'')+pocData(x.data,true)+'</div></details>').join('')+'</section></div><aside class="aside"><section class="panel"><h3>Jejak kesepakatan</h3><p>Mentee menyusun dan mengajukan. Mentor memeriksa serta menyepakati. Asmen mencatat versi yang disepakati.</p><p class="version-id" style="margin-top:14px">ID POC: '+esc(r.id)+'</p><div class="notice">Target POC tidak dapat diubah melalui ABC atau Raport.</div></section><section class="panel"><h3>Lanjutkan perjalanan</h3><div class="intro-links">'+button('Buka ABC terkait →','nav','data-page="abc"')+button('Baca Raport →','nav','data-page="raport"')+'</div></section></aside></div>'}
function pocText(r){const v=LEAP.last(r),d=v.data,p=LEAP.person(r.menteeId);return ['PERSONAL OUTCOME CONTRACT — IPB LEAP','SIMULASI LOKAL · '+p.name+' · '+BIDANG[p.field].nama+' · '+p.pathway,'Versi '+v.number+' · '+v.status,'Judul: '+d.title,'Arah: '+d.summary,'Kondisi awal: '+d.baseline,'Periode baseline: '+d.baselinePeriod,'Bukti baseline: '+d.baselineUrl,'Alasan: '+d.reason,'Outcome: '+d.outcome,...d.kpis.map((k,i)=>'\nKPI '+(i+1)+': '+k.name+'\nAcuan Bidang: '+k.fieldKpi+'\nBaseline: '+k.baseline+' '+k.unit+'\n'+Object.entries(LEAP.PERIODS).map(([code,label])=>label+': '+k.targets[code]+' '+k.unit).join('\n')+'\nCara ukur: '+k.measurement+'\nRencana bukti: '+k.evidencePlan),'\nRencana 90 hari:',...d.steps.map((s,i)=>(i+1)+'. '+s.action+' · '+dt(s.date)),'Dukungan: '+d.support,'Risiko: '+d.risk,'Mitigasi: '+d.mitigation,'\nPengajuan dan kesepakatan hanya simulasi lokal.'].join('\n')}
function scopedAbcs(){if(state.queue)return db().abcs.filter(r=>LEAP.visiblePeople(ctx()).some(p=>p.id===r.menteeId));return LEAP.abcs(db(),state.personId)}
function abcList(){const rs=scopedAbcs();return pagehead(state.queue?'Worksheet ABC kelompok':'Worksheet ABC','Catatan kegiatan, komitmen, dan pemeriksaan tindak lanjut dalam satu alur.',state.role==='mentee'?button('＋ Buat ABC baru','nav','data-page="abc-form"','primary'):'')+'<div class="grid3 stats"><div class="metric"><b>'+rs.length+'</b><span>Total catatan ABC</span></div><div class="metric"><b>'+rs.filter(r=>ABC.status(r)==='Diajukan').length+'</b><span>Menunggu pemeriksaan catatan</span></div><div class="metric"><b>'+rs.filter(ABC.pending).length+'</b><span>Menunggu tindak lanjut</span></div></div><section class="panel"><div class="section-head row spread"><div><h2>'+(state.queue?'Catatan kelompok':'Catatan '+esc(person().name.split(' ')[0]))+'</h2><p>Status catatan dan status komitmen dicatat terpisah.</p></div>'+(state.role==='asmen'&&!state.queue?button('Lihat antrean kelompok','nav','data-page="abc" data-queue="true"'):'')+'</div><div class="toolbar"><label>Pencarian<input type="search" id="abcSearch" aria-label="Cari ABC" placeholder="Cari kegiatan, mentee, atau komitmen…" value="'+esc(filter.q)+'"></label><label>Kegiatan<select id="abcActivity" aria-label="Filter kegiatan ABC">'+opts([['','Semua kegiatan'],...ABC.ACTIVITIES],filter.activity)+'</select></label><label>Status catatan<select id="abcStatus" aria-label="Filter status catatan">'+opts([['','Semua status catatan'],...ABC.STATUSES],filter.status)+'</select></label><label>Status komitmen<select id="abcCommitment" aria-label="Filter status komitmen">'+opts([['','Semua status komitmen'],...ABC.COMMITMENTS],filter.commitment)+'</select></label></div><div id="abcResults" aria-live="polite"></div></section><div class="notice">ABC lengkap menunjukkan pemahaman dan rencana. Perkembangan dibuktikan melalui tindakan dan hasil. Status ABC tidak menjadi skor atau level capaian KPI.</div>'}
function drawAbcs(){const rs=scopedAbcs().filter(r=>{const d=ABC.latest(r).data;return (!filter.q||[d.activity,d.action,d.awareness,LEAP.person(r.menteeId).name].join(' ').toLowerCase().includes(filter.q.toLowerCase()))&&(!filter.activity||d.activity===filter.activity)&&(!filter.status||ABC.status(r)===filter.status)&&(!filter.commitment||ABC.commitment(r)===filter.commitment)}).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));$('#abcResults').innerHTML=rs.length?'<p class="hint" style="margin-bottom:10px">'+rs.length+' catatan ditampilkan</p><div class="tablewrap"><table class="table abc-table"><thead><tr><th scope="col">Kegiatan / tanggal</th><th scope="col">Komitmen</th><th scope="col">Tenggat</th><th scope="col">Status catatan</th><th scope="col">Status komitmen</th><th scope="col">Detail</th></tr></thead><tbody>'+rs.map(r=>{const d=ABC.latest(r).data;return '<tr><td><span class="title">'+esc(d.activity||'Kegiatan belum dipilih')+'</span>'+(state.queue?'<span class="hint">'+esc(LEAP.person(r.menteeId).name)+'</span>':'')+'<span class="date">'+dt(d.activityDate)+'</span></td><td>'+esc(d.action||'Komitmen belum diisi')+'</td><td>'+dt(d.deadline)+'</td><td>'+badge(ABC.status(r))+'</td><td>'+badge(ABC.commitment(r),true)+'</td><td>'+button('Buka','nav','data-page="abc-detail" data-id="'+r.id+'" data-person="'+r.menteeId+'" aria-label="Buka '+esc(d.activity||'draft')+' '+esc(LEAP.person(r.menteeId).name)+'"','small')+'</td></tr>'}).join('')+'</tbody></table></div>':empty(scopedAbcs().length?'Belum ada catatan yang cocok':'Mulai dari pengalaman pertamamu',scopedAbcs().length?'Ganti kata kunci atau hapus filter pencarian.':'Tulis pemahaman baru, pilih satu langkah terbaik, lalu tetapkan tindakan berikutnya.',scopedAbcs().length?button('Hapus filter','clear-abc-filters'):(state.role==='mentee'?button('Buat ABC pertama','nav','data-page="abc-form"','primary'):'')+button('Lihat contoh fiktif','realm'));}
function abcForm(){if(!draft)return '';const pv=LEAP.last(db().pocs[state.personId]),rs=LEAP.abcs(db(),state.personId),r=rs.find(x=>x.id===state.abcId),pending=rs.filter(x=>x.id!==state.abcId&&ABC.pending(x));return pagehead(r?'Perbaiki catatan ABC':'Buat catatan ABC','Tulis singkat dan jujur. Draft boleh belum lengkap.',button('← Daftar ABC','nav','data-page="abc"'))+(pending.length?'<div class="notice warn"><b>'+pending.length+' komitmen sebelumnya belum selesai diperiksa.</b><p>Kamu tetap boleh menyimpan refleksi kegiatan baru. Tindak lanjut dicatat pada komitmen asal.</p><div class="row" style="margin-top:8px">'+pending.slice(0,3).map(x=>button(esc(ABC.latest(x).data.activity),'nav','data-page="abc-detail" data-id="'+x.id+'"','small')).join('')+'</div></div>':'')+(r&&ABC.status(r)==='Perlu perbaikan'?'<div class="notice warn"><b>Catatan perbaikan Asmen</b><p>'+esc(r.reviews[r.reviews.length-1]?.note)+'</p></div>':'')+'<div class="step-links"><a href="#abc-activity">01 · Kegiatan</a><a href="#abc-a">A · Awareness</a><a href="#abc-b">B · Best Step</a><a href="#abc-c">C · Commitment</a></div><div class="layout"><form id="abcForm" class="stack" novalidate>'+formErrors()+'<section class="panel" id="abc-activity"><div class="formtitle"><span class="letter">01</span><div><h2>Kegiatan &amp; konteks</h2><p>Identitas, Bidang, dan pathway mengikuti akun contoh di atas.</p></div></div><div class="fields"><div class="grid2">'+field('activity','Kegiatan *','select',draft.activity,'',[['','Pilih kegiatan'],...ABC.ACTIVITIES])+field('activityDate','Tanggal kegiatan *','date',draft.activityDate)+'</div>'+field('previousId','Komitmen sebelumnya · opsional','select',draft.previousId,'Pilih catatan asal yang akan dibahas saat check-in.',[['','Belum ada / tidak terkait'],...rs.filter(x=>x.id!==state.abcId).map(x=>[x.id,(ABC.latest(x).data.activity||'Draft')+' · '+dt(ABC.latest(x).data.activityDate)])])+field('kpiId','Referensi KPI POC · opsional','select',draft.kpiId,pv?'Referensi hanya memberi konteks. Target tidak diubah melalui ABC.':'POC belum tersedia. Kamu tetap bisa mengisi dan mengajukan ABC.',[['','Tanpa referensi POC'],...(pv?.data.kpis||[]).map(k=>[k.id,k.name||'KPI belum diberi nama'])])+field('targetPeriod','Target bertahap terkait · opsional','select',draft.targetPeriod,'',[['','Tidak terkait periode tertentu'],...Object.entries(LEAP.PERIODS)])+'<p class="hint">'+(draft.pocRef?'Konteks tersimpan: '+esc(draft.pocRef):'ABC tidak mewajibkan POC, terutama pada Kick-off.')+'</p></div></section><section class="panel" id="abc-priorities" '+(draft.activity==='Kick-off'?'':'hidden')+'><div class="formtitle"><span class="letter lime">3</span><div><h2>Tiga Prioritas Belajar Pribadi</h2><p>Wajib lengkap khusus ABC Kick-off.</p></div></div>'+draft.priorities.map((p,i)=>'<div class="priority"><h3>Prioritas '+(i+1)+'</h3><div class="fields">'+field('priorities.'+i+'.ability','Kemampuan yang ingin dikembangkan '+(i+1)+' *','text',p.ability)+field('priorities.'+i+'.why','Mengapa prioritas '+(i+1)+' penting? *','text',p.why)+field('priorities.'+i+'.practice','Cara melatih prioritas '+(i+1)+' *','text',p.practice)+'</div></div>').join('')+'</section><section class="panel" id="abc-a"><div class="formtitle"><span class="letter">A</span><div><h2>Awareness</h2><p>Temukan pemahaman baru dari pengalaman.</p></div></div><div class="notice" id="guideA"></div>'+field('awareness','Apa yang saya pahami? *','textarea',draft.awareness,'Apa yang saya sadari tentang diri, pekerjaan, masalah, atau cara kerja saya? Fakta atau pengalaman apa yang mendasarinya?')+'<p class="count" id="countA"></p></section><section class="panel" id="abc-b"><div class="formtitle"><span class="letter">B</span><div><h2>Best Step</h2><p>Pilih satu langkah yang jelas.</p></div></div><div class="notice" id="guideB"></div><div class="fields">'+field('bestStep','Apa satu langkah terbaik berikutnya? *','textarea',draft.bestStep,'Langkah apa yang paling membantu pengembangan saya?')+field('reason','Mengapa langkah ini dipilih? *','textarea',draft.reason)+'</div><p class="count" id="countB"></p></section><section class="panel" id="abc-c"><div class="formtitle"><span class="letter lime">C</span><div><h2>Commitment</h2><p>Tindakan konkret yang dapat dibahas saat check-in.</p></div></div><div class="notice" id="guideC"></div><p class="hint" style="margin-bottom:18px">Contoh: mewawancarai 10 calon pelanggan di luar jaringan teman. Tenggat 4 Desember 2026. Bukti: catatan wawancara.</p><div class="fields">'+field('action','Tindakan yang akan dikerjakan *','textarea',draft.action)+'<p class="count" id="countC"></p>'+field('deadline','Tenggat komitmen *','date',draft.deadline)+field('evidencePlan','Bukti yang akan dibawa *','textarea',draft.evidencePlan,'Ini rencana bukti. Tautan hasil aktual diisi pada tindak lanjut catatan ini.')+field('support','Dukungan yang diperlukan *','textarea',draft.support,'Dari siapa dan untuk apa? Boleh menulis “Tidak ada”.')+'</div>'+saveActions('abc','Ajukan ABC lokal →')+'</section></form><aside class="aside"><section class="panel"><h3>Singkat, konkret, jujur</h3><p>Maksimal tiga kalimat pada bagian A, gabungan langkah dan alasan bagian B, serta tindakan bagian C. Jawaban tidak dipotong otomatis.</p><div class="notice">Asmen memeriksa kelengkapan dan kejelasan. Tindakan serta hasil diperiksa terpisah pada tindak lanjut.</div></section><section class="panel"><h3>Satu sumber catatan</h3><p>Saat check-in, buka komitmen asal dan tulis hasilnya. Kamu tidak perlu menyalin ulang refleksi ke formulir lain.</p></section></aside></div>'}
function updateAbcGuide(){if(!draft||state.page!=='abc-form')return;const g=ABC.GUIDES[draft.activity]||['Pilih kegiatan untuk melihat pertanyaan bantuan.','Pilih satu langkah berikutnya dan alasan memilihnya.','Tentukan tindakan, tenggat, rencana bukti, dan dukungan.'];['A','B','C'].forEach((k,i)=>$('#guide'+k).textContent=g[i]);$('#abc-priorities').hidden=draft.activity!=='Kick-off';[['A',draft.awareness],['B',[draft.bestStep,draft.reason].filter(Boolean).join(' ')],['C',draft.action]].forEach(([k,t])=>{const n=ABC.sentenceCount(t);$('#count'+k).textContent=n+' / 3 kalimat'+(n>3?' · Ringkas sebelum mengajukan':'');$('#count'+k).classList.toggle('over',n>3)})}
function abcData(d){return block('A — Apa yang saya pahami?',d.awareness)+block('B — Satu langkah terbaik berikutnya',d.bestStep)+block('Alasan memilih langkah',d.reason)+block('C — Tindakan yang akan dikerjakan',d.action)+'<div class="grid2" style="margin-top:17px">'+block('Tenggat komitmen',dt(d.deadline))+block('Rencana bukti',d.evidencePlan)+'</div>'+block('Dukungan',d.support)+(d.activity==='Kick-off'?'<details class="history"><summary>Tiga Prioritas Belajar Pribadi</summary>'+d.priorities.map((p,i)=>'<div><h3>Prioritas '+(i+1)+'</h3>'+block('Kemampuan',p.ability)+block('Mengapa penting',p.why)+block('Cara melatihnya',p.practice)+'</div>').join('')+'</details>':'')}
function reportData(f){return '<div class="evidence"><div class="eyebrow">Laporan mentee · '+ts(f.at)+'</div>'+block('Tindakan yang benar-benar dijalankan',f.actualAction)+block('Hasil aktual',f.result)+'<div class="block"><div class="data-label">Tautan bukti hasil aktual</div>'+links(f.links)+'</div>'+block('Pembelajaran atau hambatan',f.learning)+block('Langkah berikutnya',f.nextStep)+'</div>'}
function abcDetail(){const r=db().abcs.find(x=>x.id===state.abcId);if(!r||!LEAP.access(ctx(),r.menteeId))return empty('Catatan tidak dapat dibuka','Pilih catatan dari daftar yang sesuai dengan peranmu.',button('Daftar ABC','nav','data-page="abc"'));const v=ABC.latest(r),d=v.data,st=ABC.status(r),f=r.followups[r.followups.length-1],check=r.checks[r.checks.length-1],pv=db().pocs[r.menteeId]?.versions.find(x=>x.id===d.pocVersionId);let controls=button('← Daftar ABC','nav','data-page="abc"')+button('Salin teks ABC','copy-abc');if(state.role==='mentee'&&['Draft','Perlu perbaikan'].includes(st))controls+=button(st==='Draft'?'Lanjutkan draft':'Perbaiki ABC','nav','data-page="abc-form" data-id="'+r.id+'"','primary');
let review='';if(state.role==='asmen'&&st==='Diajukan')review='<form id="abcReviewForm" class="fields" style="margin-top:20px" novalidate>'+field('abcDecision','Hasil pemeriksaan catatan','select','Sudah diperiksa','',['Sudah diperiksa','Perlu perbaikan'])+field('abcReviewNote','Catatan pemeriksaan / perbaikan *','textarea','')+'<div class="grid2">'+field('abcReviewDate','Tanggal pemeriksaan catatan *','date',LEAP.today())+block('Pemeriksa',LEAP.actor(ctx()))+'</div><p class="field-error" id="abcReviewError" role="alert"></p><button type="submit" class="btn primary">Simpan pemeriksaan catatan</button></form>';
let report='';if(state.role==='mentee'&&['Diajukan','Sudah diperiksa'].includes(st))report='<details class="history" '+(!f?'open':'')+'><summary>'+(f?'Tambahkan laporan tindakan baru':'Isi laporan tindakan aktual')+'</summary><form id="actionReportForm" class="fields" novalidate>'+field('actualAction','Tindakan yang benar-benar dijalankan *','textarea','','Jika belum dijalankan, jelaskan keadaan sebenarnya.')+field('result','Hasil aktual *','textarea','')+field('links','Tautan bukti hasil aktual · opsional','textarea','','Satu tautan http/https per baris. Diperlukan untuk pemeriksaan status Selesai.')+field('learning','Pembelajaran atau hambatan *','textarea','')+field('nextStep','Langkah berikutnya *','textarea','')+'<p class="field-error" id="actionReportError" role="alert"></p><button type="submit" class="btn primary">Simpan laporan tindakan</button><p class="hint">Laporan baru menambah riwayat; laporan lama tetap tersedia.</p></form></details>';
let inspect='';if(state.role==='asmen'&&st==='Sudah diperiksa'&&f)inspect='<form id="actionCheckForm" class="fields" style="margin-top:20px" novalidate>'+field('commitmentStatus','Status komitmen','select','','',[['','Pilih status komitmen'],...ABC.COMMITMENTS.slice(1)])+field('checkNote','Catatan pemeriksaan tindak lanjut *','textarea','')+'<div class="grid2">'+field('checkDate','Tanggal pemeriksaan tindak lanjut *','date',LEAP.today())+block('Pemeriksa',LEAP.actor(ctx()))+'</div><p class="field-error" id="actionCheckError" role="alert"></p><button type="submit" class="btn primary">Simpan pemeriksaan tindak lanjut</button></form>';
return pagehead(d.activity||'Draft ABC','Catatan refleksi · '+dt(d.activityDate),controls)+'<div class="row" style="margin-bottom:20px">'+badge(st)+badge(ABC.commitment(r),true)+'<span class="hint">Versi '+v.number+' · '+ts(v.at)+'</span></div><div class="layout"><div class="stack"><section class="panel"><h2>Catatan ABC</h2><div style="margin-top:20px">'+abcData(d)+'</div><details class="history"><summary>Konteks POC &amp; komitmen sebelumnya</summary>'+block('Referensi POC',d.pocRef||'Tidak ada. ABC boleh digunakan sebelum POC tersedia.')+(pv?'<p class="hint">POC versi '+pv.number+' · '+esc(d.targetPeriod?LEAP.PERIODS[d.targetPeriod]:'Tanpa periode tertentu')+'</p>':'')+(d.previousId&&db().abcs.some(x=>x.id===d.previousId)?button('Buka komitmen sebelumnya →','nav','data-page="abc-detail" data-id="'+esc(d.previousId)+'"','subtle'):'')+'<p class="hint">Referensi hanya memberi konteks; target POC tidak diubah melalui ABC.</p></details></section><section class="panel"><h2>Pemeriksaan catatan</h2><p class="hint" style="margin:9px 0 15px">Memeriksa kelengkapan dan kejelasan jawaban mentee.</p>'+(r.reviews.length?r.reviews.map(x=>'<div class="evidence"><div class="row spread">'+badge(x.decision)+'<span class="hint">'+dt(x.date)+'</span></div><p class="data-text" style="margin-top:10px">'+esc(x.note)+'</p><p class="hint">'+esc(x.checker)+' · memeriksa versi '+x.version+'</p></div>').join(''):'<p class="hint">Belum ada pemeriksaan catatan.</p>')+review+(state.role!=='asmen'?'<div class="notice">Asisten Mentor mencatat pemeriksaan secara terpisah dari jawaban mentee.</div>':'')+'</section><section class="panel" id="action-followup"><div class="formtitle"><span class="letter lime">↗</span><div><h2>Tindak lanjut komitmen</h2><p>Bagian ini menjadi bahan check-in bersama Asmen.</p></div></div><div class="notice"><b>Merujuk komitmen sebelumnya</b><p class="data-text">'+esc(d.action||'Komitmen belum diisi')+'</p><p>Tenggat '+dt(d.deadline)+' · Rencana bukti: '+esc(d.evidencePlan||'Belum diisi')+'</p></div>'+(f?reportData(f):'<p class="hint">Belum ada laporan tindakan aktual. Rencana bukti belum menjadi bukti hasil.</p>')+report+'<div style="border-top:1px solid var(--line);padding-top:20px;margin-top:20px"><h3>Pemeriksaan tindak lanjut oleh Asmen</h3><div class="row" style="margin:12px 0">'+badge(ABC.commitment(r),true)+'</div>'+(check?'<div class="evidence">'+block('Catatan Asmen',check.note)+'<p class="hint">'+esc(check.checker)+' · '+dt(check.date)+' · '+ts(check.at)+'</p></div>':'<p class="hint">Belum ada pemeriksaan tindak lanjut.</p>')+(check&&f&&check.followupId!==f.id?'<div class="notice warn">Ada laporan tindakan baru yang belum diperiksa. Status di atas berasal dari pemeriksaan sebelumnya.</div>':'')+inspect+(!inspect&&state.role==='asmen'?'<p class="hint">Periksa catatan dan tunggu laporan tindakan mentee sebelum mencatat pemeriksaan tindak lanjut.</p>':'')+'</div></section><section class="panel"><h2>Riwayat &amp; versi</h2><p class="hint" style="margin:9px 0">Versi refleksi, laporan, dan pemeriksaan sebelumnya tidak ditimpa.</p>'+[...r.versions].reverse().map(x=>'<details class="history"><summary>Versi '+x.number+' · '+esc(x.action)+' · '+ts(x.at)+'</summary><div>'+badge(x.status)+abcData(x.data)+'</div></details>').join('')+(r.followups.length?'<details class="history"><summary>Riwayat laporan tindakan ('+r.followups.length+')</summary>'+[...r.followups].reverse().map(reportData).join('')+'</details>':'')+(r.checks.length?'<details class="history"><summary>Riwayat pemeriksaan komitmen ('+r.checks.length+')</summary>'+[...r.checks].reverse().map(x=>'<div>'+badge(x.status,true)+block('Catatan',x.note)+'<p class="hint">'+esc(x.checker)+' · '+dt(x.date)+' · laporan '+esc(x.followupId)+'</p></div>').join('')+'</details>':'')+'</section></div><aside class="aside"><section class="panel"><h3>Peran &amp; batasnya</h3><p>Mentee menulis refleksi dan laporan tindakan. Asmen memeriksa kelengkapan dan kejelasan serta tindak lanjut. Mentor membaca sebagai bahan pendampingan.</p><div class="notice">Pemeriksaan ABC tidak menetapkan strategi, mengubah target POC, atau menentukan level capaian KPI.</div></section><section class="panel"><h3>Jejak catatan</h3><p class="version-id">'+esc(r.id)+'</p><p class="hint" style="margin-top:12px">'+r.versions.length+' versi · '+r.followups.length+' laporan · '+r.checks.length+' pemeriksaan komitmen</p>'+button('Baca Raport →','nav','data-page="raport"','subtle')+'</section></aside></div>'}
function abcText(r){const d=ABC.latest(r).data,p=LEAP.person(r.menteeId);return ['WORKSHEET ABC — IPB LEAP','SIMULASI LOKAL · '+p.name,'ID: '+r.id+' · versi '+ABC.latest(r).number,'Kegiatan: '+d.activity+' · '+dt(d.activityDate),'Status catatan: '+ABC.status(r),'Status komitmen: '+ABC.commitment(r),'Referensi POC: '+(d.pocRef||'Tidak ada'),'A — Awareness\n'+d.awareness,'B — Best Step\n'+d.bestStep+'\nAlasan: '+d.reason,'C — Commitment\n'+d.action+'\nTenggat: '+dt(d.deadline)+'\nRencana bukti: '+d.evidencePlan+'\nDukungan: '+d.support,d.activity==='Kick-off'?'Tiga prioritas belajar:\n'+d.priorities.map((x,i)=>(i+1)+'. '+x.ability+'\nMengapa: '+x.why+'\nCara melatih: '+x.practice).join('\n\n'):'','Laporan tindakan:\n'+r.followups.map(x=>[ts(x.at),x.actualAction,x.result,'Bukti aktual: '+x.links,x.learning,x.nextStep].join('\n')).join('\n\n'),'Pemeriksaan catatan:\n'+r.reviews.map(x=>x.decision+' · '+x.note+' · '+x.checker+' · '+dt(x.date)).join('\n'),'Pemeriksaan komitmen:\n'+r.checks.map(x=>x.status+' · '+x.note+' · '+x.checker+' · '+dt(x.date)).join('\n')].join('\n\n')}
function periodControl(){return '<label class="period-control">Review POC<select id="periodSelect" aria-label="Review POC">'+opts(Object.entries(LEAP.PERIODS),state.period)+'</select></label>'}
function evidenceCard(e,selectIndex=null,selected=false){return '<div class="evidence">'+(selectIndex!==null?'<label class="check-label"><input type="checkbox" name="items.'+selectIndex+'.evidenceIds" data-eid="'+esc(e.reportId)+'" '+(selected?'checked':'')+' aria-label="Gunakan bukti '+esc(e.activity)+'"><span><b>'+esc(e.activity)+'</b> · '+ts(e.reportedAt)+'</span></label>':'<div class="row spread"><b class="small">'+esc(e.activity)+'</b>'+badge(e.check?'Sudah diperiksa Asmen':'Belum diperiksa',true)+'</div>')+'<p>'+esc(e.result)+'</p><div style="margin-top:8px">'+links(e.links)+'</div><p class="hint" style="margin-top:9px">'+(e.check?'Pemeriksaan: '+esc(e.check.checker)+' · '+dt(e.check.date)+' · '+esc(e.check.status):'Laporan belum diperiksa Asmen.')+'</p>'+(selectIndex===null?button('Buka catatan asal →','nav','data-page="abc-detail" data-id="'+e.abcId+'"','subtle small'):'')+'</div>'}
function raportView(){const id=state.personId,r=LEAP.review(db(),id,state.period),pub=LEAP.published(r),pv=pub?.source.poc||LEAP.agreed(db(),id),as=LEAP.abcs(db(),id),allSources=pub?.source.evidence||LEAP.evidence(db(),id),latestAction=[...as].reverse().find(x=>x.followups.length),lastReport=latestAction?.followups[latestAction.followups.length-1];let actions=periodControl()+button('Salin Raport','copy-raport');if(LEAP.canAssess(ctx(),state.period)&&!pub)actions+=button(LEAP.last(r)?'Lanjutkan penilaian':'Siapkan penilaian','nav','data-page="assessment"','primary');
return pagehead(state.period==='M12'?'Raport akhir':'Raport','Satu halaman untuk membaca perkembangan, capaian beserta bukti, dan langkah berikutnya.',actions)+'<section class="panel report-section"><div class="section-number">01 · Ringkasan perkembangan</div><div class="row spread"><h2>'+esc(person().name)+'</h2>'+badge(pub?'Diterbitkan':LEAP.last(r)?'Draft penilaian':'Belum diterbitkan')+'</div>'+monthlyCard()+'<p class="data-text" style="margin-top:16px">'+esc(pub?.data.summary||'Hasil penilaian periode ini belum diterbitkan. Catatan dan bukti tindakan di bawah menjadi bahan pendampingan; belum merupakan hasil penilaian.')+'</p><div class="grid3 stats" style="margin-bottom:0"><div class="metric"><b>'+as.length+'</b><span>Catatan ABC</span></div><div class="metric"><b>'+allSources.length+'</b><span>'+(pub?'Laporan bukti yang dirujuk':'Laporan hasil tersedia')+'</span></div><div class="metric"><b>'+as.filter(ABC.pending).length+'</b><span>Komitmen menunggu tindak lanjut</span></div></div><p class="hint" style="margin-top:12px">Jumlah catatan dan laporan adalah informasi aktivitas, tidak menjadi skor atau level capaian.</p>'+(pub?'<p class="hint" style="margin-top:12px">Diterbitkan lokal oleh '+esc(pub.actor)+' · '+ts(pub.at)+'</p>':'')+'</section><section class="panel report-section"><div class="section-number">02 · Capaian &amp; bukti</div><h2>Dari target menuju hasil aktual</h2><p class="hint" style="margin-top:9px">'+(pv?'Acuan: '+esc(pv.data.title)+' · POC versi '+pv.number+' yang kesepakatannya tercatat.':'POC yang disepakati belum tersedia. ABC tetap dapat digunakan.')+'</p>'+(pv?pv.data.kpis.map(k=>{const item=pub?.data.items.find(x=>x.kpiId===k.id),es=allSources.filter(x=>x.kpiId===k.id);return '<article class="kpi-result"><div class="row spread"><h3>'+esc(k.name)+'</h3>'+(item?badge(item.level):badge('Belum dinilai',true))+'</div><div class="baseline-target"><div><span>Baseline</span><strong>'+esc(k.baseline)+' '+esc(k.unit)+'</strong></div><div><span>Target '+state.period+'</span><strong>'+esc(k.targets[state.period])+' '+esc(k.unit)+'</strong></div><div><span>Hasil aktual</span><strong>'+esc(item?.actual||'Lihat laporan bukti')+'</strong></div></div>'+(item?block('Alasan penilaian',item.reason):'<p class="hint">Level dan alasan penilaian akan tampil setelah hasil diterbitkan.</p>')+(es.length?es.map(e=>evidenceCard(e)).join(''):'<div class="notice">Belum ada laporan bukti yang dirujuk untuk KPI ini. Saat menulis ABC, pilih referensi KPI yang sesuai.</div>')+'</article>'}).join(''):empty('Acuan POC belum tersedia','Mentee dan Mentor menyepakati POC, lalu Asmen mencatat versinya. Catatan ABC dapat dimulai lebih dulu.',button('Buka POC','nav','data-page="poc"')))+(pub?'<details class="history"><summary>Jejak sumber &amp; versi Raport</summary><p class="hint">Raport memakai salinan sumber pada saat diterbitkan. Perubahan laporan setelahnya tidak mengubah hasil terbit.</p><p class="version-id">POC '+esc(pub.source.poc.id)+' · '+pub.source.evidence.length+' laporan bukti · versi penilaian '+pub.number+'</p><ul class="source-list">'+pub.source.evidence.map(e=>'<li>Laporan '+esc(e.reportId)+' · '+esc(e.activity)+'</li>').join('')+'</ul></details>':'')+'</section><section class="panel report-section"><div class="section-number">03 · Catatan &amp; langkah berikutnya</div><h2>Apa yang perlu dilanjutkan?</h2><div class="report-note"><h3>Umpan balik pendamping</h3><p class="data-text">'+esc(pub?.data.feedback||'Umpan balik periode ini akan tampil bersama hasil yang diterbitkan.')+'</p></div><div class="report-note"><h3>Langkah berikutnya</h3><p class="data-text">'+esc(pub?.data.nextStep||lastReport?.nextStep||'Pilih satu langkah pengembangan dan catat komitmennya pada ABC.')+'</p></div><div class="row" style="margin-top:20px">'+button('Buka Worksheet ABC','nav','data-page="abc"')+button('Update bulanan','progress')+(state.role==='mentee'?button('Buat refleksi berikutnya','nav','data-page="abc-form"','primary'):'')+'</div><p class="hint" style="margin-top:16px">Nilai bulanan, status ABC, dan level capaian KPI dibaca terpisah. Nilai bulanan contoh tidak dihitung dari banyaknya ABC. Hasil Review mengikuti penilaian manual sesuai peran.</p></section>'}
function assessmentForm(){const pv=LEAP.agreed(db(),state.personId);if(!pv||!draft)return pagehead('Siapkan penilaian','Target acuan harus berasal dari POC yang telah disepakati dan dicatat.',button('← Raport','nav','data-page="raport"'))+'<section class="panel">'+empty('Kesepakatan POC belum tercatat','Selesaikan pembahasan POC bersama Mentor, lalu catat kesepakatannya sebagai Asmen.',button('Buka POC','nav','data-page="poc"','primary'))+'</section>';return pagehead(state.period==='M12'?'Penilaian akhir':'Review perkembangan',LEAP.PERIODS[state.period]+' · '+LEAP.ROLES[state.role],button('← Raport','nav','data-page="raport"'))+'<div class="notice"><b>Acuan tetap: POC versi '+pv.number+'.</b> Target tidak dapat diedit dari halaman ini. Pilih bukti yang relevan; pemeriksaan komitmen bukan penetapan level KPI.</div><div class="layout"><form id="assessmentForm" class="stack" novalidate>'+formErrors()+'<section class="panel"><div class="section-head"><h2>Capaian per KPI</h2><p>Nilai berdasarkan target, hasil aktual, dan bukti yang relevan. Tidak ada perhitungan level otomatis.</p></div>'+draft.items.map((item,i)=>{const k=pv.data.kpis.find(x=>x.id===item.kpiId),es=LEAP.evidence(db(),state.personId,k.id);return '<div class="kpi-edit"><h3>'+esc(k.name)+'</h3><div class="baseline-target"><div><span>Baseline</span><strong>'+esc(k.baseline)+' '+esc(k.unit)+'</strong></div><div><span>Target '+state.period+'</span><strong>'+esc(k.targets[state.period])+' '+esc(k.unit)+'</strong></div><div><span>Jenis</span><strong>'+({MENINGKAT:'Meningkat',MENURUN:'Menurun',MILESTONE:'Milestone'}[k.type])+'</strong></div></div><div class="fields">'+field('items.'+i+'.actual','Hasil aktual KPI '+(i+1)+' *','text',item.actual,'Gunakan hasil yang dapat dijelaskan sumber dan periodenya.')+'</div><div style="margin-top:17px"><div class="data-label">Pilih laporan bukti yang dirujuk</div>'+(es.length?es.map(e=>evidenceCard(e,i,item.evidenceIds.includes(e.reportId))).join(''):'<p class="hint">Belum ada laporan tindakan pada ABC yang terkait KPI ini.</p>')+'</div><div class="fields">'+field('items.'+i+'.level','Level capaian KPI '+(i+1)+' *','select',item.level,'',LEAP.LEVELS)+field('items.'+i+'.reason','Alasan penilaian KPI '+(i+1)+' *','textarea',item.reason,'Jelaskan hubungan target, hasil aktual, dan bukti.')+'</div><details class="history"><summary>Kriteria yang tercatat pada POC</summary>'+LEAP.LEVELS.slice(1).map(level=>block(level,k.criteria[level]||'Belum diusulkan; bahas acuan yang sesuai dengan mentor.')).join('')+'</details></div>'}).join('')+'</section><section class="panel"><h2>Ringkasan yang akan dibaca mentee</h2><div class="fields" style="margin-top:20px">'+field('summary','Ringkasan perkembangan *','textarea',draft.summary)+field('feedback','Umpan balik pendamping *','textarea',draft.feedback)+field('nextStep','Langkah berikutnya *','textarea',draft.nextStep)+'</div>'+saveActions('assessment','Terbitkan hasil lokal →')+'</section></form><aside class="aside"><section class="panel"><h3>Pembagian penilaian</h3><p>Review M3, M6, dan M9 disiapkan Senior Mentor. Penilaian akhir M12 disiapkan Tim Program dengan penugasan Admin penilaian pada simulasi ini.</p><div class="notice">Hanya hasil yang diterbitkan tampil sebagai hasil penilaian di Raport mentee. Draft tetap berada di ruang penilai.</div></section><section class="panel"><h3>Bukti tetap punya sumber</h3><p>Hasil terbit menyimpan salinan versi POC dan laporan bukti yang dirujuk. Catatan ABC dan laporan aslinya tetap tersedia.</p></section></aside></div>'}
function raportText(){const r=LEAP.review(db(),state.personId,state.period),v=LEAP.published(r),p=person();if(!v)return ['RAPORT — IPB LEAP','SIMULASI LOKAL · '+p.name,LEAP.PERIODS[state.period],'Hasil periode ini belum diterbitkan.','Catatan ABC dan bukti tindakan tersedia sebagai bahan pendampingan.'].join('\n');return ['RAPORT — IPB LEAP','SIMULASI LOKAL · '+p.name+' · '+BIDANG[p.field].nama,LEAP.PERIODS[state.period],'Diterbitkan lokal: '+ts(v.at)+' · '+v.actor,'\n1. RINGKASAN PERKEMBANGAN',v.data.summary,'\n2. CAPAIAN & BUKTI',...v.data.items.map(item=>{const k=v.source.poc.data.kpis.find(x=>x.id===item.kpiId);return k.name+'\nBaseline: '+k.baseline+' '+k.unit+'\nTarget: '+k.targets[state.period]+' '+k.unit+'\nAktual: '+item.actual+'\nLevel: '+item.level+'\nAlasan: '+item.reason+'\nBukti:\n'+v.source.evidence.filter(e=>item.evidenceIds.includes(e.reportId)).map(e=>e.activity+' · '+e.result+'\n'+e.links).join('\n')}),'\n3. CATATAN & LANGKAH BERIKUTNYA',v.data.feedback,v.data.nextStep,'\nTanpa perhitungan skor atau keputusan kelulusan otomatis.'].join('\n')}
function setPath(obj,path,value){const keys=path.split('.');let target=obj;for(let i=0;i<keys.length-1;i++)target=target[keys[i]];target[keys[keys.length-1]]=value}
function getPath(obj,path){return path.split('.').reduce((a,k)=>a?.[k],obj)}
function currentAbc(){return db().abcs.find(x=>x.id===state.abcId)}
function saveDraft(kind,submit=false){if(!draft||editKind!==kind)return false;let r;if(kind==='poc')r=transact(d=>LEAP.savePoc(d,ctx(),draft,submit));if(kind==='abc')r=transact(d=>LEAP.abcSave(d,ctx(),draft,state.abcId,submit));if(kind==='assessment')r=transact(d=>LEAP.saveReview(d,ctx(),draft,submit));if(!r)return false;dirty=false;errors={};if(kind==='abc')state.abcId=r.id;if(submit){state.page=kind==='poc'?'poc':kind==='abc'?'abc-detail':'raport';draft=null;editKind=null;render(true)}else{render();toast('Draft tersimpan · versi '+(kind==='abc'?ABC.latest(r).number:LEAP.last(r).number)+' · '+ts(LEAP.now()))}if(submit)toast(kind==='assessment'?'Hasil diterbitkan secara lokal. Tidak ada pengiriman nyata.':(kind==='poc'?'POC':'ABC')+' diajukan secara lokal. Tidak ada pengiriman nyata.');return true}
function submitDraft(kind){if(kind==='poc'){const es=LEAP.pocErrors(draft);if(Object.keys(es).length){showErrors(es);return}}if(kind==='abc'){const raw=ABC.validate(draft),es={};for(const [k,v]of Object.entries(raw))es[k.replace(/^priority-(\d+)-(\w+)$/,'priorities.$1.$2')]=v;if(Object.keys(es).length){showErrors(es);return}}if(kind==='assessment'){try{LEAP.saveReview(LEAP.clone(db()),ctx(),draft,true)}catch(e){showErrors({_form:e.message});return}}if(Object.keys(errors).length){errors={};render()}confirmAction(kind==='assessment'?'Terbitkan hasil secara lokal?':'Ajukan '+(kind==='poc'?'POC':'ABC')+' secara lokal?',kind==='assessment'?'Mentee akan dapat membaca hasil simulasi ini pada Raport. Versi POC dan laporan bukti yang dirujuk ikut disimpan sebagai jejak sumber. Tidak ada email, notifikasi, atau pengiriman ke akun lain.':'Status akan berubah menjadi Diajukan dan isian dibekukan sampai ada permintaan perbaikan. Tidak ada pengiriman ke akun lain, email, atau notifikasi nyata.',()=>saveDraft(kind,true),kind==='assessment'?'Ya, terbitkan lokal':'Ya, ajukan lokal')}
function afterForm(ok,message){if(!ok)return;dirty=false;errors={};render();toast(message)}
function val(path){return document.getElementById(inputId(path)).value.trim()}
function guide(){dialog('<h2>Coba satu perjalanan pengembangan</h2><p>Mulai dari <b>Lihat contoh</b> untuk data fiktif lintas modul. Ruang contoh terpisah dari catatan saya.</p><ol class="small"><li><b>Mentee:</b> susun POC atau tulis ABC lebih dulu. Simpan draft dan ajukan setelah lengkap.</li><li><b>Senior Mentor:</b> buka POC mentee yang sama, lalu sepakati atau minta perbaikan.</li><li><b>Asmen:</b> catat kesepakatan POC, periksa ABC, dan periksa laporan tindakan saat check-in.</li><li><b>Mentee:</b> isi tindakan dan hasil aktual pada komitmen asal. Pilih KPI terkait agar bukti dapat dirujuk pada Review.</li><li><b>Senior Mentor:</b> siapkan Review M3/M6/M9. <b>Tim Program:</b> siapkan penilaian akhir M12. Hasil yang diterbitkan dibaca pada Raport.</li></ol><p>Raport cukup tiga bagian: ringkasan perkembangan, capaian &amp; bukti, serta catatan &amp; langkah berikutnya.</p><p>Peran dan identitas adalah simulasi. Data tidak tersinkron antarperangkat. Memindahkan HTML, mode privat, atau menghapus data browser dapat memengaruhi penyimpanan.</p><div class="row">'+button('Tutup','modal-close')+button('Salin panduan singkat','copy-guide')+'</div>')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='progress'){navigate('progress');return}if(a==='monthly-source'){applyMonthlySources();return}if(a==='modal-close'){closeModal();return}if(a==='copy-unsaved'){copyRaw('ISIAN BELUM DISIMPAN — SIMULASI LOKAL\n'+unsavedText());return}if(a==='guide'){leave(guide);return}if(a==='copy-guide'){copyRaw('IPB LEAP — WORKSPACE LOKAL\n1. Mentee menyusun POC/ABC.\n2. Mentor menyepakati POC.\n3. Asmen mencatat kesepakatan dan memeriksa ABC.\n4. Mentee melaporkan tindakan; Asmen memeriksa tindak lanjut.\n5. Mentor menilai Review berkala; Tim Program menilai akhir M12.\n6. Raport menampilkan hasil terbit.\nSemua tindakan adalah simulasi lokal.');return}if(a==='realm'){switchRealm();return}if(a==='nav'){const extra={};if(b.dataset.person){if(!LEAP.access(ctx(),b.dataset.person)&&state.role!=='mentee'){toast('Mentee berada di luar cakupan peran ini.');return}extra.personId=b.dataset.person}if(b.dataset.id){const r=db().abcs.find(x=>x.id===b.dataset.id);if(!r||!LEAP.access(ctx(),r.menteeId)){toast('Catatan tidak berada dalam cakupan peran ini.');return}extra.abcId=r.id;extra.personId=r.menteeId}if(b.dataset.queue==='true')extra.queue=true;navigate(b.dataset.page,extra);return}if(a==='poc-save')saveDraft('poc');if(a==='abc-save')saveDraft('abc');if(a==='assessment-save')saveDraft('assessment');if(a==='copy-poc')copyRaw(pocText(db().pocs[state.personId]));if(a==='copy-abc')copyRaw(abcText(currentAbc()));if(a==='copy-raport')copyRaw(raportText());if(a==='clear-abc-filters'){filter={q:'',activity:'',status:'',commitment:''};render()}if(a==='add-kpi'&&editKind==='poc'&&draft.kpis.length<3){draft.kpis.push(LEAP.kpiBlank(person().field));dirty=true;render()}if(a==='remove-kpi'&&editKind==='poc'&&draft.kpis.length>1){const i=Number(b.dataset.index);confirmAction('Hapus KPI dari isian ini?','KPI akan dihapus dari draft yang sedang dibuka. Versi yang sebelumnya sudah disimpan tetap tersedia dalam riwayat.',()=>{draft.kpis.splice(i,1);dirty=true;render();return true},'Hapus dari draft')}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='abcSearch'){filter.q=el.value;drawAbcs();return}if(el.id==='peopleSearch'){peopleFilter.q=el.value;drawPeople();return}const form=el.closest('form');if(!form||!main.contains(form))return;dirty=true;const hint=main.querySelector('.save-hint');if(hint)hint.textContent='Ada perubahan yang belum disimpan. Simpan agar tersedia setelah muat ulang.';if(!draft||!['pocForm','abcForm','assessmentForm'].includes(form.id)||!el.name)return;if(el.dataset.eid){const arr=getPath(draft,el.name);if(el.checked&&!arr.includes(el.dataset.eid))arr.push(el.dataset.eid);else if(!el.checked){const i=arr.indexOf(el.dataset.eid);if(i>=0)arr.splice(i,1)}}else setPath(draft,el.name,el.type==='checkbox'?el.checked:el.value);if(editKind==='abc'&&el.name==='kpiId'){const pv=LEAP.last(db().pocs[state.personId]),k=pv?.data.kpis.find(x=>x.id===el.value);draft.pocVersionId=k?pv.id:'';draft.pocRef=k?pv.data.title+' · '+k.name:''}if(editKind==='abc')updateAbcGuide()});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='monthlyPeriod'){monthlyPeriod=el.value;prefs();render();return}if(el.id==='roleSelect'){const selected=el.value;el.value=state.role;changeRole(selected);return}if(el.id==='personSelect'){const id=el.value;el.value=state.personId;leave(()=>{if(state.role!=='mentee'&&!LEAP.access(ctx(),id)){toast('Mentee berada di luar kelompok pendamping.');return}state.personId=id;state.page='home';state.queue=false;draft=null;dirty=false;errors={};prefs();render(true)});return}if(el.id==='groupSelect'){const group=el.value;el.value=state.groupId;leave(()=>{state.groupId=group;state.page='home';state.queue=false;draft=null;dirty=false;normalize();prefs();render(true)});return}if(el.id==='periodSelect'){const period=el.value;el.value=state.period;leave(()=>{state.period=period;draft=null;dirty=false;errors={};prefs();render(true)});return}const abcFilters={abcActivity:'activity',abcStatus:'status',abcCommitment:'commitment'};if(abcFilters[el.id]){filter[abcFilters[el.id]]=el.value;drawAbcs();return}if(el.id==='peopleField'){peopleFilter.field=el.value;drawPeople();return}if(el.id==='peopleGroup'){peopleFilter.group=el.value;drawPeople();return}if(draft&&el.name&&(el.name==='kpiId'||el.name.endsWith('.type'))){const currentScroll=window.scrollY;render();window.scrollTo(0,currentScroll);document.getElementById(el.id)?.focus({preventScroll:true})}});
document.addEventListener('submit',e=>{const form=e.target;if(!main.contains(form))return;e.preventDefault();if(form.id==='monthlyUpdateForm'){saveMonthlyUpdate(e.submitter?.value==='submit');return}if(form.id==='pocForm'){submitDraft('poc');return}if(form.id==='abcForm'){submitDraft('abc');return}if(form.id==='assessmentForm'){submitDraft('assessment');return}if(form.id==='pocDecisionForm'){afterForm(transact(d=>LEAP.decidePoc(d,ctx(),state.personId,val('pocDecision'),val('pocNote')),'decisionError'),'Keputusan Mentor tersimpan secara lokal.');return}if(form.id==='pocRecordForm'){afterForm(transact(d=>LEAP.recordPoc(d,ctx(),state.personId,val('recordNote'),val('recordDate')),'recordError'),'Kesepakatan dan versi POC tercatat secara lokal.');return}if(form.id==='abcReviewForm'){afterForm(transact(d=>LEAP.abcReview(d,ctx(),state.abcId,val('abcDecision'),val('abcReviewNote'),val('abcReviewDate')),'abcReviewError'),'Pemeriksaan catatan ABC tersimpan.');return}if(form.id==='actionReportForm'){const f={};for(const k of ['actualAction','result','links','learning','nextStep'])f[k]=val(k);afterForm(transact(d=>LEAP.reportAction(d,ctx(),state.abcId,f),'actionReportError'),'Laporan tindakan tersimpan.');return}if(form.id==='actionCheckForm'){afterForm(transact(d=>LEAP.inspectAction(d,ctx(),state.abcId,val('commitmentStatus'),val('checkNote'),val('checkDate')),'actionCheckError'),'Pemeriksaan tindak lanjut tersimpan.');return}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
window.addEventListener('storage',e=>{if(Object.values(LEAP.KEYS).includes(e.key)){const changedRealm=Object.keys(LEAP.KEYS).find(k=>LEAP.KEYS[k]===e.key);if(changedRealm===state.realm){storageError('Data berubah di tab lain. Salin isian yang belum disimpan, lalu muat ulang sebelum menyimpan lagi.')}else{load(changedRealm)}}});
normalize();render();

function monthlyCard(){const sample=state.personId==='mentee-01';const months=[['2026-07','Juli 2026'],['2026-08','Agustus 2026'],['2026-09','September 2026']];const data={'2026-07':{score:'78',mentor:'—',asmen:'—'},'2026-08':{score:'82',mentor:'—',asmen:'—'},'2026-09':{score:'86,4',mentor:'88,0',asmen:'84,8'}};const v=sample?data[monthlyPeriod]:null;return '<div class="monthly-report"><div class="row spread"><h3>Nilai bulanan</h3><label class="period-control">Bulan nilai<select id="monthlyPeriod">'+opts(months,monthlyPeriod)+'</select></label></div>'+(v?'<div class="monthly-score"><b>'+v.score+'</b>'+(monthlyPeriod==='2026-09'?'<span class="status lime">A · Sangat Baik</span>':'')+'</div><p class="hint">'+esc(person().name)+' · Batch 2026 · '+esc(LEAP.GROUPS[person().group].name)+' · '+esc(months.find(x=>x[0]===monthlyPeriod)?.[1])+'</p><svg role="img" aria-label="Tren nilai Juli 78, Agustus 82, September 86,4" viewBox="0 0 300 90"><path d="M10 64L150 46L290 22L290 90L10 90Z" fill="#E4EBF8"/><path d="M10 64L150 46L290 22" fill="none" stroke="#3157A5" stroke-width="3"/><circle cx="290" cy="22" r="7" fill="#D4FF3A" stroke="#32306F" stroke-width="2"/></svg><div class="row spread hint"><span>Jul · 78</span><span>Agu · 82</span><span>Sep · 86,4</span></div><div class="grid2" style="margin-top:14px"><div><span class="hint">Dari Mentor</span><p><b>'+v.mentor+'</b></p></div><div><span class="hint">Dari Asmen</span><p><b>'+v.asmen+'</b></p></div></div><p class="hint" style="margin-top:13px">Data contoh dari Beranda. Nilai dan rincian September dipertahankan; rumus penilaian belum dihubungkan ke catatan browser.</p>':'<p class="notice">Nilai bulanan untuk mentee dan bulan ini belum tersedia. Tidak ada nilai yang dihitung otomatis dari ABC.</p>')+'</div>';}
function monthRecords(){return LEAP.abcs(db(),state.personId).filter(r=>(ABC.latest(r).data.activityDate||'').startsWith('2026-10'));}
function monthlyLatest(){return db().monthlyUpdates?.[state.personId+'|2026-10']?.versions.at(-1);}
function progressView(){const saved=monthlyLatest(),reports=LEAP.evidence(db(),state.personId).filter(e=>monthRecords().some(r=>r.id===e.abcId));const d=saved?.data||{achievement:'',obstacle:'',nextStep:'',sourceIds:[]};const readOnly=state.role!=='mentee';return pagehead('Update progres · Oktober 2026','Pilih laporan ABC yang sudah ada, tinjau ringkasannya, lalu simpan update bulanan. Tidak ada pengiriman nyata.')+'<section class="panel"><h2>Ambil dari tindakan yang sudah dicatat</h2><p class="hint">Rencana bukti tetap berada di ABC. Ringkasan ini memakai laporan tindakan dan hasil aktual, dengan sumber yang dapat dibuka.</p><div id="monthlySources">'+(reports.length?reports.map(e=>'<label class="evidence check-label"><input type="checkbox" name="monthlySource" value="'+esc(e.reportId)+'" '+(d.sourceIds.includes(e.reportId)?'checked':'')+' '+(readOnly?'disabled':'')+'><span><b>'+esc(e.activity)+'</b><br>'+esc(e.result)+'<br><span class="hint">'+(e.check?'Sudah diperiksa Asmen':'Belum diperiksa Asmen')+'</span></span></label>'+button('Buka catatan asal →','nav','data-page="abc-detail" data-id="'+esc(e.abcId)+'"','small')).join(''):'<div class="notice">Belum ada laporan hasil ABC untuk Oktober. Kamu tetap bisa menulis update dan menyimpannya. <a href="WorksheetABC.dc.html?role=mentee">Buka Worksheet ABC →</a></div>')+'</div>'+(readOnly?'':button('Gunakan laporan terpilih','monthly-source'))+'</section><section class="panel"><form id="monthlyUpdateForm"><div class="fields"><label class="field">Capaian bulan ini<textarea name="achievement" '+(readOnly?'readonly':'')+'>'+esc(d.achievement)+'</textarea></label><label class="field">Pembelajaran atau hambatan<textarea name="obstacle" '+(readOnly?'readonly':'')+'>'+esc(d.obstacle)+'</textarea></label><label class="field">Langkah berikutnya<textarea name="nextStep" '+(readOnly?'readonly':'')+'>'+esc(d.nextStep)+'</textarea></label></div><p class="hint" style="margin-top:12px">'+(saved?esc(saved.status)+' · versi '+saved.number+' · '+ts(saved.at):'Belum ada update tersimpan.')+'</p>'+(readOnly?'':'<div class="actions"><button class="btn" type="submit" value="draft">Simpan draft</button><button class="btn primary" type="submit" value="submit">Ajukan update lokal</button></div>')+'</form>'+(saved?'<details class="history"><summary>Riwayat update bulanan</summary>'+db().monthlyUpdates[state.personId+'|2026-10'].versions.slice().reverse().map(v=>'<div><b>Versi '+v.number+' · '+esc(v.status)+'</b><p class="hint">'+ts(v.at)+'</p>'+block('Capaian',v.data.achievement)+block('Hambatan',v.data.obstacle)+block('Langkah berikutnya',v.data.nextStep)+'</div>').join('')+'</details>':'')+'</section>';}
function applyMonthlySources(){const selected=[...document.querySelectorAll('[name="monthlySource"]:checked')].map(x=>x.value),sources=LEAP.evidence(db(),state.personId).filter(e=>selected.includes(e.reportId)),form=document.getElementById('monthlyUpdateForm');if(!sources.length){toast('Pilih minimal satu laporan hasil.');return}if([...form.querySelectorAll('textarea')].some(x=>x.value.trim())&&!confirm('Gunakan ringkasan laporan terpilih untuk mengganti isian update yang sedang terbuka? Riwayat tersimpan tetap tersedia.'))return;for(const [name,key] of [['achievement','result'],['obstacle','learning'],['nextStep','nextStep']])form.elements[name].value=sources.map(e=>e.activity+': '+e[key]).join('\n');dirty=true;toast('Ringkasan terisi. Tinjau kembali sebelum mengajukan.');}
function saveMonthlyUpdate(submit){const form=document.getElementById('monthlyUpdateForm'),data={sourceIds:[...document.querySelectorAll('[name="monthlySource"]:checked')].map(x=>x.value)};for(const name of ['achievement','obstacle','nextStep'])data[name]=form.elements[name].value.trim();if(submit&&['achievement','obstacle','nextStep'].some(k=>!data[k])){toast('Lengkapi tiga bagian sebelum mengajukan.');form.querySelector('textarea').focus();return}const result=transact(d=>LEAP.saveMonthly(d,ctx(),data,submit));if(result){dirty=false;render();toast(submit?'Update diajukan secara lokal. Tidak ada pengiriman ke akun lain.':'Draft update bulanan tersimpan.');}}
